def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    high_budget_threat = 0
    desperate_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 140:
                high_budget_threat += 1
            if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive_opponents:
        return min(budget, 18.0)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    slots = max(1, int(supply // WATER_REQ))
    scarcity = slots <= 1

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if scarcity:
        urgency += 2
    if high_budget_threat >= 2:
        urgency += 1
    if desperate_count >= 2:
        urgency += 1

    if day >= 8:
        urgency += 1

    if urgency <= 1:
        bid = 12.0 if not scarcity else 28.0
    elif urgency == 2:
        bid = 26.0 if not scarcity else 52.0
    elif urgency == 3:
        bid = 45.0 if not scarcity else 82.0
    elif urgency == 4:
        bid = 68.0 if not scarcity else 118.0
    else:
        bid = 95.0 if not scarcity else 155.0

    if highest_prev > 0:
        if urgency >= 4:
            target = highest_prev + 3.0
            if target > bid:
                bid = target
        elif urgency >= 2 and scarcity:
            target = highest_prev * 0.72
            if target > bid:
                bid = target
        elif highest_prev >= 150 and hp >= 7 and no_water_days == 0:
            bid = min(bid, 18.0)
        elif avg_prev < 40 and urgency >= 2:
            target = highest_prev + 1.5
            if target > bid:
                bid = target

    income_buffer = DAILY_SALARY * max(0, 10 - day)
    if hp >= 7 and no_water_days == 0 and budget < 90 and not scarcity:
        bid = min(bid, 20.0)
    elif budget < 50:
        bid = min(bid, max(12.0, budget * 0.7))
    elif budget > income_buffer and urgency >= 4:
        bid = max(bid, min(budget, highest_prev + 5.0 if highest_prev > 0 else 120.0))

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, highest_prev + 4.0 if highest_prev > 0 else 110.0)

    if scarcity and hp >= 8 and no_water_days == 0 and highest_prev >= 170:
        bid = min(bid, 22.0)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = day_context['day']

    # Alive opponents
    alive = []
    for k, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((k, o))

    if not alive:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Immediate reaction from yesterday traces only
    prev_bids = []
    for _, o in alive:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Determine how many full water units supply can cover this day
    # (Used to calibrate aggressiveness; avoid float-index issues by not indexing arrays.)
    max_units = int(supply // float(WATER_REQ)) if WATER_REQ > 0 else 0

    # Baseline: secure moderate share
    # If supply is tight (<= 18), we must bid more to avoid being squeezed.
    tight_supply = supply <= 18.0

    # If opponents previously pushed very high, we undercut slightly unless low HP forces us.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if my_status['hp'] <= 2 or my_status.get('no_water_days', 0) >= 2:
            bid = DAILY_SALARY * 0.95
        else:
            bid = max(DAILY_SALARY * 0.55, highest_prev_bid * 0.75)
    else:
        if my_status['hp'] <= 2 or my_status.get('no_water_days', 0) >= 2:
            bid = DAILY_SALARY * 0.85
        else:
            bid = DAILY_SALARY * (0.65 if tight_supply else 0.55)

    # If supply can cover only 1 unit, increase slightly to avoid losing the last slot
    if max_units <= 1:
        bid *= 1.15

    # Safety cap by budget
    bid = float(min(my_status['budget'], bid))

    # Ensure non-negative
    if bid < 0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_players = len(alive_opponents) + 1
    fair_share = day_context['supply'] / num_players

    # Analyze yesterday's competition
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Base strategy: bid higher if HP is low, otherwise aim for efficient allocation
    if my_status['hp'] < 4:
        bid = DAILY_SALARY * 0.8
    elif fair_share >= WATER_REQ:
        bid = DAILY_SALARY * 0.4
    else:
        bid = DAILY_SALARY * 0.6

    # Adjust for aggressive opponents
    if yesterday_bids and max(yesterday_bids) > bid:
        bid = min(my_status['budget'], max(bid, max(yesterday_bids) * 0.95))

    return float(min(my_status['budget'], bid))
